 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    centers = []
    # Each object is a four-point diamond: its cardinal neighbors are 2s.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and all(grid[r + dr][c + dc] == 2 for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))):
                centers.append((r, c))
    out = [row[:] for row in grid]
    for r, c in centers:
        for dr, dc in ((0, 1), (1, 0)):
            aligned = [p for p in centers if (p[0] == r if dr == 0 else p[1] == c) and (p[1] > c if dc == 1 else p[0] > r)]
            if not aligned:
                continue
            # Connect only the nearest diamond in this direction.
            rr, cc = min(aligned, key=lambda p: p[1] if dc else p[0])
            for k in range(2, (cc - c) if dc else (rr - r) - 1):
                y, x = r + dr * k, c + dc * k
                if out[y][x] == 0:
                    out[y][x] = 1
    return out
